import{_t as e,it as t,n,rt as r}from"./chunks/framework.C1oW5ckO.js";var i=JSON.parse(`{"title":"Plugin kit","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/tools/plugin-kit/docs/index.md"},"headers":[],"relativePath":"tools/plugin-kit/docs/index.md","filePath":"tools/plugin-kit/docs/index.md","lastUpdated":1792252169000}`),a={name:`tools/plugin-kit/docs/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="plugin-kit" tabindex="-1">Plugin kit <a class="header-anchor" href="#plugin-kit" aria-label="Permalink to “Plugin kit”">​</a></h1><p><code>@pumpkin-plugins/plugin-kit</code> gives Pumpkin plugins shared building blocks for lifecycle hooks, commands, scheduled work, logging, data folders, plugin messages, and binary payloads. Its testing helpers provide in-memory replacements for host services, so you can exercise plugin behavior without starting a server.</p><h2 id="plugin-lifecycle" tabindex="-1">Plugin lifecycle <a class="header-anchor" href="#plugin-lifecycle" aria-label="Permalink to “Plugin lifecycle”">​</a></h2><p>Build your plugin on <code>PluginBase</code>, passing its <code>PluginInfo</code> and package version to the constructor. Implement <code>onPluginLoad</code> for setup and, when needed, <code>onPluginUnload</code> for cleanup. Register the instance with <code>registerPlugin</code> to enable the non-blocking Pumpkin Market update check. Export <code>handleTask</code> from your plugin entry point as well; it dispatches the kit&#39;s scheduled work and then passes other task IDs to the Pumpkin API handler.</p><p>The scheduling helpers accept whole, nonnegative tick counts. Repeating tasks must run at least once per tick, while delayed tasks may run immediately with a delay of zero. If scheduling fails, the kit releases the callback; when a delayed callback runs, it releases it before execution.</p><h2 id="data-commands-and-tests" tabindex="-1">Data, commands, and tests <a class="header-anchor" href="#data-commands-and-tests" aria-label="Permalink to “Data, commands, and tests”">​</a></h2><p>When the plugin has the <code>fs.*.data</code> permission, the WASI data-folder adapter provides access to its mounted <code>data</code> directory. Its paths are relative to that directory. You can list entries, inspect files, read them in full or at chosen offsets, create directories, replace files atomically, and remove files or empty directories.</p><p>The command helpers build a typed command tree and register its handlers. The same tree supplies the documented command paths, so the registered commands and their documentation stay aligned. The generated API reference lists the kit&#39;s module entry points and exact types.</p><p>For unit tests, use <code>MemoryFiles</code>, the fake command host, and the in-memory logger to stand in for filesystem, command, and logging services. These fakes also expose common mistakes: for example, <code>MemoryFiles</code> rejects file and directory conflicts and operations on missing directories, and its file handles reject reads after they are closed.</p>`,9)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};